/* Same native DEM metadata, UTM conversion and Terrarium decoding as RF Sim. */
(function(root){
const nongDEM={pixel:30.1469654783933,left:823716.347994793,top:2029199.8061258246,width:4770,height:2671,tileSize:1024,path:'dem/nong-khai/tiles-final',label:'หนองคาย'};
const defaultDEM={pixel:30.1469654783933,left:508982.0284003669,top:1798304.1975268102,width:1992,height:1992,tileSize:1024,path:'dem/default-site/tiles-final',label:'พิกัดเริ่มต้น'};
function utm47(lat,lon){const a=6378137,f=1/298.257223563,e=f*(2-f),e4=e*e,e6=e4*e,ep=e/(1-e),phi=lat*Math.PI/180,L=(lon-99)*Math.PI/180,s=Math.sin(phi),co=Math.cos(phi),t=Math.tan(phi),T=t*t,C=ep*co*co,A=co*L,N=a/Math.sqrt(1-e*s*s),M=a*((1-e/4-3*e4/64-5*e6/256)*phi-(3*e/8+3*e4/32+45*e6/1024)*Math.sin(2*phi)+(15*e4/256+45*e6/1024)*Math.sin(4*phi)-(35*e6/3072)*Math.sin(6*phi));return{x:500000+.9996*N*(A+(1-T+C)*A**3/6+(5-18*T+T*T+72*C-58*ep)*A**5/120),y:.9996*(M+N*t*(A*A/2+(5-T+9*C+4*C*C)*A**4/24+(61-58*T+T*T+600*C-330*ep)*A**6/720))}}
const cache=new Map();
async function loadTile(url,native,signal){if(cache.has(url))return cache.get(url);const res=await fetch(url,{signal});if(!res.ok)throw Error('โหลด DEM ไม่สำเร็จ HTTP '+res.status);const bitmap=await createImageBitmap(await res.blob()),cv=document.createElement('canvas');cv.width=bitmap.width;cv.height=bitmap.height;const ctx=cv.getContext('2d',{willReadFrequently:true});ctx.drawImage(bitmap,0,0);bitmap.close();const expected=native?1024:256;if(cv.width!==expected||cv.height!==expected)throw Error('ขนาด DEM ไม่ถูกต้อง');const data=RFTerrain.decode(ctx.getImageData(0,0,cv.width,cv.height).data,native);cache.set(url,data);while(cache.size>300)cache.delete(cache.keys().next().value);return data}
function geometry(c){const link=MWMath.inverse(c.a,c.b);if(link.distance<10||link.distance>200000)throw Error('รองรับระยะลิงก์ 10 m ถึง 200 km');const count=Math.max(2,Math.ceil(link.distance/c.step)),xs=new Set(Array.from({length:count+1},(_,i)=>i*link.distance/count));for(const o of c.obstacles)for(const x of [o.x-o.width/2,o.x,o.x+o.width/2])if(x>0&&x<link.distance)xs.add(x);const width=Math.max(10,2*MWMath.fresnel(c.freq,link.distance/2,link.distance/2));const rows=[...xs].sort((a,b)=>a-b).map(x=>{const p=MWMath.direct(c.a,link.bearing,x),az=x<link.distance-.01?MWMath.inverse(p,c.b).bearing:link.bearing;return {x,samples:Array.from({length:17},(_,j)=>{const offset=(j-8)*width/8;return {...(offset===0?p:MWMath.direct(p,az+(offset>0?90:-90),Math.abs(offset))),offset}})}});return {...link,rows,width,step:link.distance/count}}
async function load(c,signal,progress){const g=geometry(c),points=g.rows.flatMap(r=>r.samples),z=13;const native=[defaultDEM,nongDEM].find(d=>points.every(p=>{const u=utm47(p.lat,p.lon),x=(u.x-d.left)/d.pixel,y=(d.top-u.y)/d.pixel;return x>=1&&x<d.width-1&&y>=1&&y<d.height-1}));async function source(d){const size=d?d.tileSize:256,jobs=new Map();for(const p of points){let px,py;if(d){const u=utm47(p.lat,p.lon);px=(u.x-d.left)/d.pixel-.5;py=(d.top-u.y)/d.pixel-.5}else{px=(p.lon+180)/360*2**z*256-.5;py=(1-Math.asinh(Math.tan(p.lat*Math.PI/180))/Math.PI)/2*2**z*256-.5}for(const dx of [0,1])for(const dy of [0,1]){const x=Math.floor((Math.floor(px)+dx)/size),y=Math.floor((Math.floor(py)+dy)/size);jobs.set(x+':'+y,{x,y})}}if(jobs.size>1024)throw Error('เส้นทางใช้ DEM มากเกินไป กรุณาลดระยะ');const list=[...jobs.values()],entries=[];let done=0;for(let i=0;i<list.length;i+=6){await Promise.all(list.slice(i,i+6).map(async t=>{const url=d?`${d.path}/${t.x}-${t.y}.png`:`https://s3.amazonaws.com/elevation-tiles-prod/terrarium/${z}/${t.x}/${t.y}.png`,data=await loadTile(url,!!d,signal);entries.push({...t,data});progress(`อ่าน DEM ${++done}/${list.length} แผ่น`)}));if(signal.aborted)throw new DOMException('หยุดแล้ว','AbortError')}const sampler=RFTerrain.sampler(c.a,{native:d||null,z,size,entries},utm47),denom=111.195*Math.cos(c.a.lat*Math.PI/180);let missing=0;const rows=g.rows.map(r=>({...r,samples:r.samples.map(p=>{const ground=sampler((p.lon-c.a.lon)*denom,(p.lat-c.a.lat)*111.195);if(ground===null)missing++;return {...p,ground:ground===null?NaN:ground}})}));return {...g,rows,missing,source:d?'DEM '+d.label:'AWS Terrarium z13',pixelM:d?d.pixel:40075016.7*Math.cos((c.a.lat+c.b.lat)/2*Math.PI/180)/(256*2**z),tiles:list.length}}
if(native){try{const t=await source(native);if(!t.missing)return t;progress('DEM ในพื้นที่ไม่ครบ กำลังใช้ AWS ทั้งเส้นทาง')}catch(e){if(signal.aborted)throw e;progress('กำลังใช้ DEM AWS สำรอง')}}return source(null)}
root.MWDEM={geometry,load};
})(globalThis);
